"use client";

/**
 * Bar rise: a bar chart whose bars grow from the baseline one after another,
 * each value counting up above it, the last bar landing in the primary colour.
 * The "look where it went" beat of a product film.
 *
 * Written by Better Design. Painted from the theme prop, so the bars take the
 * product's ink and the final bar takes its primary colour.
 */
import { loadFont } from "@remotion/google-fonts/Inter";
import { AbsoluteFill, interpolate, useCurrentFrame } from "remotion";
import { easings, mix, pickFont, type VideoTheme, useVideoTheme, withAlpha } from "@/lib/bd-video";

const { fontFamily: INTER } = loadFont("normal", { weights: ["500", "600", "700"], subsets: ["latin"] });

/** Frames before the first bar starts, between bar starts, and per bar. */
const FIRST_AT = 14;
const STAGGER = 7;
const GROW = 26;

const CHART_W = 1380;
const CHART_H = 560;

export interface BarRiseProps {
  /** One label per bar, read under the baseline. */
  labels?: string[];
  /** One value per bar. Bars scale against the largest value. */
  values?: number[];
  /** Appended to every value, such as "%" or "k". */
  unit?: string;
  /** The line above the chart that says what is measured. */
  title?: string;
  /** Digits after the decimal point on the value labels. */
  decimals?: number;
  theme?: Partial<VideoTheme>;
  /** A CSS font family the project has loaded. Defaults to the theme's face, then Inter. */
  font?: string;
}

const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const format = (n: number, decimals: number): string =>
  n.toLocaleString("en-US", { minimumFractionDigits: decimals, maximumFractionDigits: decimals });

/** Grow a row of bars from the baseline in turn, counting each value up. */
export function BarRise({
  labels = ["Jan", "Feb", "Mar", "Apr", "May", "Jun"],
  values = [24, 31, 29, 42, 51, 68],
  unit = "",
  title = "Monthly results",
  decimals = 0,
  theme: themeOverride,
  font,
}: BarRiseProps) {
  const theme = useVideoTheme(themeOverride);
  const frame = useCurrentFrame();
  const family = pickFont(font, theme, INTER);

  const count = Math.max(1, values.length);
  const max = Math.max(...values, 1);
  const slot = CHART_W / count;
  const barW = Math.min(slot * 0.56, 150);

  const titleT = easings.out(interpolate(frame, [0, 16], [0, 1], clamp));
  const axisT = easings.out(interpolate(frame, [4, 24], [0, 1], clamp));

  return (
    <AbsoluteFill style={{ background: theme.background, alignItems: "center", justifyContent: "center", fontFamily: family }}>
      <div style={{ width: CHART_W, display: "flex", flexDirection: "column", gap: 56 }}>
        <div
          style={{
            fontSize: 44,
            fontWeight: 600,
            letterSpacing: "-0.02em",
            color: theme.foreground,
            opacity: titleT,
            transform: `translateY(${(1 - titleT) * 16}px)`,
          }}
        >
          {title}
        </div>
        <div style={{ position: "relative", height: CHART_H }}>
          {[0.25, 0.5, 0.75].map((g) => (
            <div
              key={g}
              style={{
                position: "absolute",
                left: 0,
                right: 0,
                bottom: CHART_H * g,
                height: 1,
                background: withAlpha(theme.foreground, 0.06 * axisT),
              }}
            />
          ))}
          {values.map((v, i) => {
            const start = FIRST_AT + i * STAGGER;
            const t = easings.out(interpolate(frame, [start, start + GROW], [0, 1], clamp));
            const h = Math.max(0, (v / max) * (CHART_H - 70) * t);
            const isLast = i === count - 1;
            const fill = isLast ? theme.primary : mix(theme.background, theme.foreground, 0.16);
            return (
              <div
                key={i}
                style={{
                  position: "absolute",
                  bottom: 0,
                  left: slot * i + (slot - barW) / 2,
                  width: barW,
                  height: CHART_H,
                  display: "flex",
                  flexDirection: "column",
                  justifyContent: "flex-end",
                  alignItems: "center",
                }}
              >
                <div
                  style={{
                    fontSize: 34,
                    fontWeight: isLast ? 700 : 600,
                    color: isLast ? theme.primary : theme.mutedForeground,
                    fontVariantNumeric: "tabular-nums",
                    marginBottom: 16,
                    opacity: interpolate(t, [0, 0.25], [0, 1], clamp),
                    whiteSpace: "nowrap",
                  }}
                >
                  {format(v * t, decimals)}
                  {unit}
                </div>
                <div style={{ width: "100%", height: h, background: fill, borderRadius: `${Math.min(14, barW / 6)}px ${Math.min(14, barW / 6)}px 0 0` }} />
              </div>
            );
          })}
          <div
            style={{
              position: "absolute",
              left: 0,
              bottom: -1,
              height: 2,
              width: `${axisT * 100}%`,
              background: withAlpha(theme.foreground, 0.22),
            }}
          />
        </div>
        <div style={{ position: "relative", height: 40, marginTop: -28 }}>
          {labels.slice(0, count).map((l, i) => {
            const start = FIRST_AT + i * STAGGER;
            const t = easings.out(interpolate(frame, [start, start + 14], [0, 1], clamp));
            return (
              <div
                key={i}
                style={{
                  position: "absolute",
                  left: slot * i,
                  width: slot,
                  textAlign: "center",
                  fontSize: 30,
                  fontWeight: 500,
                  color: i === count - 1 ? theme.foreground : theme.mutedForeground,
                  opacity: t,
                }}
              >
                {l}
              </div>
            );
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
}
